-- Written to be re-runnable: production applies each statement on its own, so a run
-- interrupted part way must be able to start again from the top.
-- Edits a traveller makes to the checklist on their own case: a new sentence for one item (REWORD)
-- or a personal reminder (OWN_ITEM). One new table, nothing existing is touched. The table was
-- generated by drizzle-kit and made re-runnable here. Until this runs the code finds the table
-- missing, shows no edit controls, and the case page reads exactly as before. Postgres keeps only
-- the first 63 characters of a name, so the foreign key guards compare that much.
CREATE TABLE IF NOT EXISTS "case_checklist_edits" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"mission_id" uuid NOT NULL,
	"applicant_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"pack_requirement_id" uuid,
	"wording" text NOT NULL,
	"done_at" timestamp with time zone,
	"created_by_account_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "case_checklist_edits_reword_unique" UNIQUE("mission_id","pack_requirement_id"),
	CONSTRAINT "case_checklist_edits_kind_known" CHECK ("case_checklist_edits"."kind" in ('REWORD', 'OWN_ITEM')),
	CONSTRAINT "case_checklist_edits_shape" CHECK (("case_checklist_edits"."kind" = 'REWORD') = ("case_checklist_edits"."pack_requirement_id" is not null)),
	CONSTRAINT "case_checklist_edits_done_own_only" CHECK ("case_checklist_edits"."done_at" is null or "case_checklist_edits"."kind" = 'OWN_ITEM'),
	CONSTRAINT "case_checklist_edits_wording_length" CHECK (char_length(btrim("case_checklist_edits"."wording")) between 1 and 400 and char_length("case_checklist_edits"."wording") <= 400)
);
--> statement-breakpoint
DO $fk$ BEGIN
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('case_checklist_edits_mission_id_missions_id_fk', 63)) THEN
		ALTER TABLE "case_checklist_edits" ADD CONSTRAINT "case_checklist_edits_mission_id_missions_id_fk" FOREIGN KEY ("mission_id") REFERENCES "public"."missions"("id") ON DELETE cascade ON UPDATE no action;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('case_checklist_edits_applicant_id_applicants_id_fk', 63)) THEN
		ALTER TABLE "case_checklist_edits" ADD CONSTRAINT "case_checklist_edits_applicant_id_applicants_id_fk" FOREIGN KEY ("applicant_id") REFERENCES "public"."applicants"("id") ON DELETE cascade ON UPDATE no action;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('case_checklist_edits_pack_requirement_id_pack_requirements_id_fk', 63)) THEN
		ALTER TABLE "case_checklist_edits" ADD CONSTRAINT "case_checklist_edits_pack_requirement_id_pack_requirements_id_fk" FOREIGN KEY ("pack_requirement_id") REFERENCES "public"."pack_requirements"("id") ON DELETE cascade ON UPDATE no action;
	END IF;
	IF NOT EXISTS (SELECT 1 FROM pg_constraint WHERE conname = left('case_checklist_edits_created_by_account_id_accounts_id_fk', 63)) THEN
		ALTER TABLE "case_checklist_edits" ADD CONSTRAINT "case_checklist_edits_created_by_account_id_accounts_id_fk" FOREIGN KEY ("created_by_account_id") REFERENCES "public"."accounts"("id") ON DELETE set null ON UPDATE no action;
	END IF;
END $fk$;
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "case_checklist_edits_mission_idx" ON "case_checklist_edits" USING btree ("mission_id","kind","created_at");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "case_checklist_edits_applicant_idx" ON "case_checklist_edits" USING btree ("applicant_id");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "case_checklist_edits_requirement_idx" ON "case_checklist_edits" USING btree ("pack_requirement_id");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "case_checklist_edits_created_by_idx" ON "case_checklist_edits" USING btree ("created_by_account_id");
